SELECT

FROM T_GENERAL_LEDGER

    IS_DELETED = 0

        AND BOOK_ID = #{param.bookId}


        AND TENANT_ID = #{param.tenantId}


        AND SUBJECT_CODE = #{param.subjectCode}


        AND PERIOD = #{param.accountingPeriod}


        AND PERIOD >= #{param.beginDate}


        AND PERIOD <= #{param.endDate}


ORDER BY PERIOD, SUBJECT_CODE

SELECT COUNT(1)
FROM T_GENERAL_LEDGER

    IS_DELETED = 0

        AND BOOK_ID = #{param.bookId}


        AND TENANT_ID = #{param.tenantId}


        AND SUBJECT_CODE = #{param.subjectCode}


        AND PERIOD = #{param.accountingPeriod}


        AND PERIOD >= #{param.beginDate}


        AND PERIOD <= #{param.endDate}

SELECT

FROM T_GENERAL_LEDGER
WHERE SUBJECT_CODE = #{subjectCode}
AND IS_DELETED = 0

    AND PERIOD = #{period}

AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
ORDER BY PERIOD, SUBJECT_CODE

SELECT #{auxiliaryType} as auxiliaryType, SUBJECT_CODE as auxiliaryValue, SUBJECT_CODE as subjectCode, SUM(DEBIT_AMOUNT + CREDIT_AMOUNT) as amount, COUNT(1) as count FROM T_GENERAL_LEDGER WHERE SUBJECT_CODE = #{subjectCode} AND IS_DELETED = 0
AND PERIOD = #{period}
AND BOOK_ID = #{bookId} AND TENANT_ID = #{tenantId} GROUP BY SUBJECT_CODE ORDER BY amount DESC FETCH FIRST 10 ROWS ONLY

SELECT SUBJECT_CODE, PERIOD, OPENING_BALANCE, DEBIT_AMOUNT, CREDIT_AMOUNT, CLOSING_BALANCE, CREATE_TIME FROM T_GENERAL_LEDGER
IS_DELETED = 0
AND BOOK_ID = #{param.bookId}
AND TENANT_ID = #{param.tenantId}
AND SUBJECT_CODE LIKE CONCAT(#{param.subjectCode}, '%')
AND PERIOD = #{param.accountingPeriod}
AND PERIOD >= #{param.beginDate}
AND PERIOD <= #{param.endDate}
ORDER BY PERIOD, SUBJECT_CODE

SELECT
    COUNT(DISTINCT SUBJECT_CODE) as subjectCount,
    SUM(DEBIT_AMOUNT) as totalDebit,
    SUM(CREDIT_AMOUNT) as totalCredit,
    SUM(DEBIT_AMOUNT) - SUM(CREDIT_AMOUNT) as netAmount,
    COUNT(1) as entryCount
FROM T_GENERAL_LEDGER

    IS_DELETED = 0

        AND BOOK_ID = #{bookId}


        AND TENANT_ID = #{tenantId}


        AND PERIOD = #{period}


        AND LENGTH(SUBJECT_CODE) = #{subjectLevel}


        AND SUBSTR(SUBJECT_CODE, 1, 1) = #{subjectType}
